import React, { useState, useEffect } from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import Table from '../../../components/ui/Table/Table';
import api from '../../../api/api'; // Importa o nosso cliente da API

const ListAdminsPage = () => {
  const [admins, setAdmins] = useState([]); // Estado para guardar os admins vindos da API
  const headers = ['ID', 'Nome', 'Email', 'Data de Criação'];

  // useEffect é executado quando o componente é montado
  useEffect(() => {
    // Função assíncrona para ir buscar os dados
    const fetchAdmins = async () => {
      try {
        const response = await api.get('/admins'); // Faz um pedido GET para /api/admins
        setAdmins(response.data); // Guarda os dados no estado
      } catch (error) {
        console.error("Erro ao buscar administradores:", error);
      }
    };

    fetchAdmins(); // Chama a função
  }, []); // O array vazio [] garante que isto só é executado uma vez

  return (
    <ContentWrapper title="Listar Admins Nível 1">
      <Table headers={headers} data={admins} />
    </ContentWrapper>
  );
};

export default ListAdminsPage;
